import { test, expect } from '@playwright/test';

test.describe('Dropdown Menu Keyboard Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><div id="dropdown-container"><button id="dropdown-trigger">Menu</button><div id="dropdown-menu" role="menu" style="display:none;"><div role="menuitem" tabindex="0">Option 1</div><div role="menuitem" tabindex="-1">Option 2</div><div role="menuitem" tabindex="-1">Option 3</div></div></div><script>const trigger = document.getElementById("dropdown-trigger");const menu = document.getElementById("dropdown-menu");const items = menu.querySelectorAll("[role=menuitem]");let currentIndex = 0;trigger.addEventListener("click", () => {menu.style.display = menu.style.display === "none" ? "block" : "none";if(menu.style.display === "block") items[0].focus();});document.addEventListener("keydown", (e) => {if(menu.style.display === "none") return;if(e.key === "ArrowDown") {e.preventDefault();items[currentIndex].tabIndex = -1;currentIndex = (currentIndex + 1) % items.length;items[currentIndex].tabIndex = 0;items[currentIndex].focus();}if(e.key === "ArrowUp") {e.preventDefault();items[currentIndex].tabIndex = -1;currentIndex = (currentIndex - 1 + items.length) % items.length;items[currentIndex].tabIndex = 0;items[currentIndex].focus();}});</script></body></html>');
  });

  test('should navigate down through dropdown items with arrow down key', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Menu' });
    await trigger.click();

    const firstItem = page.getByRole('menuitem').first();
    await expect(firstItem).toBeFocused();

    await page.keyboard.press('ArrowDown');
    const secondItem = page.getByRole('menuitem').nth(1);
    await expect(secondItem).toBeFocused();

    await page.keyboard.press('ArrowDown');
    const thirdItem = page.getByRole('menuitem').nth(2);
    await expect(thirdItem).toBeFocused();
  });

  test('should navigate up through dropdown items with arrow up key', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Menu' });
    await trigger.click();

    const firstItem = page.getByRole('menuitem').first();
    await expect(firstItem).toBeFocused();

    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    const thirdItem = page.getByRole('menuitem').nth(2);
    await expect(thirdItem).toBeFocused();

    await page.keyboard.press('ArrowUp');
    const secondItem = page.getByRole('menuitem').nth(1);
    await expect(secondItem).toBeFocused();

    await page.keyboard.press('ArrowUp');
    await expect(firstItem).toBeFocused();
  });

  test('should wrap around when navigating past last item with arrow down', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Menu' });
    await trigger.click();

    const firstItem = page.getByRole('menuitem').first();
    await expect(firstItem).toBeFocused();

    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('ArrowDown');
    await expect(firstItem).toBeFocused();
  });

  test('should wrap around when navigating past first item with arrow up', async ({ page }) => {
    const trigger = page.getByRole('button', { name: 'Menu' });
    await trigger.click();

    const firstItem = page.getByRole('menuitem').first();
    await expect(firstItem).toBeFocused();

    await page.keyboard.press('ArrowUp');
    const thirdItem = page.getByRole('menuitem').nth(2);
    await expect(thirdItem).toBeFocused();
  });
});
